INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation) VALUES
  ('grammar_vocab', 'A1', 'gap_fill', 'tenses', 'The train _____ for Paris at 8 a.m. every morning.', to_jsonb(ARRAY['leaves','departs']::text[]), 'leaves', 'Simple present tense for a scheduled, habitual action; the time marker ''every morning'' signals a routine.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'tenses', 'Yesterday, the team _____ a new printer for the office.', to_jsonb(ARRAY['bought','purchased']::text[]), 'bought', 'Simple past irregular verb (buy → bought) for a completed action, marked by ''yesterday''.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'tenses', 'Last month, we _____ a major client because of a pricing dispute.', to_jsonb(ARRAY['lost']::text[]), 'lost', 'Simple past irregular verb (lose → lost) with a clear past time marker, ''last month''.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'tenses', 'The company has already signed the lease, so next month it _____ to move to a bigger office.', to_jsonb(ARRAY['is going','plans','is planning','is due','is set']::text[]), 'is going', '''Be going to'' expresses a future plan that has already been decided, signalled by ''has already signed the lease''.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'tenses', 'The company _____ three new offices since it went public in 2015.', to_jsonb(ARRAY['has opened','has established','has launched']::text[]), 'has opened', 'Present perfect for actions occurring within an unfinished time period introduced by ''since''.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'tenses', 'The phone is ringing right now - I _____ it.', to_jsonb(ARRAY['will answer','will get','will take']::text[]), 'will answer', '''Will'' is used for a spontaneous decision made at the moment of speaking.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'tenses', 'According to company policy, all invoices _____ by the finance team within 30 days of receipt.', to_jsonb(ARRAY['are processed']::text[]), 'are processed', 'Passive voice (present simple) is used because the focus is on the invoices, the receiver of the action, not on who performs it.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'tenses', 'The manager _____ a phone call when the client suddenly walked into the office.', to_jsonb(ARRAY['was making','was having']::text[]), 'was making', 'Past continuous for an action in progress that was interrupted by a shorter past action expressed in the simple past (''walked in'').'),
  ('grammar_vocab', 'C1', 'gap_fill', 'tenses', 'If she _____ the extra training last year, she would be qualified for the promotion now.', to_jsonb(ARRAY['had taken','had done']::text[]), 'had taken', 'Mixed conditional combining a past unreal condition (had taken) with a present hypothetical result (would be qualified).'),
  ('grammar_vocab', 'C1', 'gap_fill', 'tenses', 'By the time the auditor arrived, the accountant _____ the same spreadsheet for six hours straight.', to_jsonb(ARRAY['had been checking','had been working on','had been reviewing']::text[]), 'had been checking', 'Past perfect continuous emphasizes the duration of an action that was ongoing up to a specific point in the past.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'tenses', 'The auditor insisted that the manager _____ all receipts before month-end.', to_jsonb(ARRAY['submit','should submit']::text[]), 'submit', 'Mandative subjunctive after verbs like ''insist that'' uses the base form of the verb regardless of the subject.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'tenses', 'The new safety measures _____ implemented months ago, but budget cuts kept delaying the rollout.', to_jsonb(ARRAY['should have been','ought to have been']::text[]), 'should have been', 'Modal perfect passive expressing an unfulfilled past obligation or expectation.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'prepositions', 'The calendar is _____ the wall.', to_jsonb(ARRAY['on']::text[]), 'on', 'We use "on" to describe something attached to or positioned on a surface such as a wall.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'prepositions', 'I don''t like driving _____ night.', to_jsonb(ARRAY['at']::text[]), 'at', '"At night" is the standard fixed time expression in English; "in" or "on" cannot be used here.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'prepositions', 'The sales director usually travels _____ plane for international meetings.', to_jsonb(ARRAY['by']::text[]), 'by', '"By" is used with a mode of transport (by plane, by car, by train) when no article precedes the noun.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'prepositions', 'The report is due _____ the end of the week.', to_jsonb(ARRAY['at','by']::text[]), 'at', '"At the end of" is a fixed time expression used to mark a deadline point.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'prepositions', 'He applied _____ the marketing position last week.', to_jsonb(ARRAY['for']::text[]), 'for', 'The verb "apply" is followed by "for" when referring to a job, position, or request.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'prepositions', 'She is very proud _____ her team''s achievements.', to_jsonb(ARRAY['of']::text[]), 'of', 'The adjective "proud" is always followed by the preposition "of".'),
  ('grammar_vocab', 'B2', 'gap_fill', 'prepositions', 'The marketing budget must account _____ all promotional expenses.', to_jsonb(ARRAY['for']::text[]), 'for', '"Account for" is a fixed business collocation meaning to explain or make up the total of something.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'prepositions', 'Employees are entitled _____ five weeks of paid leave per year.', to_jsonb(ARRAY['to']::text[]), 'to', '"Entitled to" is the fixed collocation used to state what someone has a right to receive.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'prepositions', '_____ the absence of the manager, her deputy will chair the meeting.', to_jsonb(ARRAY['In']::text[]), 'In', '"In the absence of" is a formal fixed expression meaning "when someone is not present".'),
  ('grammar_vocab', 'C1', 'gap_fill', 'prepositions', 'The new marketing strategy was developed _____ a view to increasing brand awareness.', to_jsonb(ARRAY['with']::text[]), 'with', '"With a view to" is a formal fixed expression meaning "with the purpose or intention of".'),
  ('grammar_vocab', 'C2', 'gap_fill', 'prepositions', '_____ the wake of the scandal, the CEO resigned within days.', to_jsonb(ARRAY['In']::text[]), 'In', '"In the wake of" is an idiomatic fixed expression meaning "as a direct result of" or "following" an event.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'prepositions', 'The board approved the merger _____ the basis of the auditor''s report.', to_jsonb(ARRAY['on']::text[]), 'on', '"On the basis of" is a fixed expression meaning "using something as the foundation for a decision".'),
  ('grammar_vocab', 'A1', 'gap_fill', 'business_vocab', 'I use my _____ to write emails and check my schedule every morning at work.', to_jsonb(ARRAY['computer','laptop']::text[]), 'computer', 'A computer is the electronic device used for tasks like writing emails and checking a schedule; no other common office item performs these functions.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'business_vocab', 'You need to type your secret _____ before you can log into the computer system.', to_jsonb(ARRAY['password']::text[]), 'password', 'A password is the secret set of letters or numbers needed to access a computer system; it is the specific item required to log in.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'business_vocab', 'The _____ answers the phone and greets visitors when they first arrive at the office.', to_jsonb(ARRAY['receptionist']::text[]), 'receptionist', 'The receptionist is the employee whose job is to welcome visitors and handle incoming calls at the front desk.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'business_vocab', 'Because I worked two extra hours after my shift ended, I will be paid _____ for that time.', to_jsonb(ARRAY['overtime']::text[]), 'overtime', 'Overtime is the pay received for working beyond normal working hours, which matches the description of extra hours worked after a shift.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'business_vocab', 'New employees at the company must complete a three-month _____ period before their permanent contract is confirmed.', to_jsonb(ARRAY['probation','probationary']::text[]), 'probation', 'A probation period is a trial period during which a new employee''s performance is assessed before their job becomes permanent.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'business_vocab', 'If you want to leave your job, your contract requires you to work a one-month _____ before your last day.', to_jsonb(ARRAY['notice period']::text[]), 'notice period', 'A notice period is the length of time an employee must keep working after resigning, as required by their employment contract.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'business_vocab', 'The company''s _____ fell sharply this year because production costs rose faster than the prices it charged customers.', to_jsonb(ARRAY['profit margin','profits','margins']::text[]), 'profit margin', 'Profit margin is the percentage of revenue left as profit after costs; it specifically falls when costs rise faster than prices, unlike total revenue.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'business_vocab', 'The two rival companies agreed to combine into a single, larger organisation through a _____.', to_jsonb(ARRAY['merger']::text[]), 'merger', 'A merger is the formal combination of two companies into one new organisation, distinct from an acquisition where one company simply buys another.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'business_vocab', 'Because of falling sales, the company had to make fifty employees _____, ending their jobs due to a lack of work rather than poor performance.', to_jsonb(ARRAY['redundant']::text[]), 'redundant', 'Redundant describes employees whose jobs are eliminated because there is no longer enough work for them, as opposed to being dismissed for poor performance.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'business_vocab', 'The new manager wants to _____ the approval process by removing unnecessary steps and making it faster.', to_jsonb(ARRAY['streamline','simplify']::text[]), 'streamline', 'To streamline a process means to make it more efficient by cutting out unnecessary steps, matching the context of removing steps to increase speed.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'business_vocab', 'To focus on its core business, the conglomerate decided to _____ its underperforming retail division as part of a broader restructuring.', to_jsonb(ARRAY['divest']::text[]), 'divest', 'To divest means to sell off a business asset or division, which matches the context of the conglomerate selling its underperforming retail arm.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'business_vocab', 'The contract requires the supplier to _____ the client against any financial losses caused by defective products.', to_jsonb(ARRAY['indemnify','protect']::text[]), 'indemnify', 'To indemnify someone means to compensate or protect them against financial loss or damage, which fits a contract clause covering defective products.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'phrasal_verbs', 'Before the training video starts, please _____ and turn off your phones.', to_jsonb(ARRAY['sit down']::text[]), 'sit down', '"Sit down" means to move from a standing to a seated position, a common everyday A1 phrasal verb used in instructions.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'phrasal_verbs', 'After the long meeting, the whole team decided to _____ for pizza to celebrate.', to_jsonb(ARRAY['go out','head out']::text[]), 'go out', '"Go out" means to leave home or work to visit a restaurant or social place, fitting the idea of going somewhere to eat together.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'phrasal_verbs', 'The system crashed halfway through the form, so I had to _____ from the beginning.', to_jsonb(ARRAY['start over','start again']::text[]), 'start over', '"Start over" means to begin again from the beginning after something has gone wrong, matching the crashed system.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'phrasal_verbs', 'Could you _____ these agendas to everyone before the meeting starts?', to_jsonb(ARRAY['hand out','give out','pass out']::text[]), 'hand out', '"Hand out" means to distribute copies of something to a group of people, here the meeting agendas.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'phrasal_verbs', 'The marketing team needs to _____ a new slogan before the campaign launch.', to_jsonb(ARRAY['come up with','think up','dream up']::text[]), 'come up with', '"Come up with" means to think of or produce an idea, plan, or solution, fitting the need for a new slogan.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'phrasal_verbs', 'Can you _____ a short presentation for tomorrow''s client meeting?', to_jsonb(ARRAY['put together','prepare','throw together']::text[]), 'put together', '"Put together" means to prepare or assemble something, such as a presentation, from different parts.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'phrasal_verbs', 'The legal team will _____ a new contract for the supplier by next week.', to_jsonb(ARRAY['draw up','draft']::text[]), 'draw up', '"Draw up" means to prepare a formal written document, such as a contract or agreement.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'phrasal_verbs', 'The company will _____ the new expense policy gradually across all departments, effective September.', to_jsonb(ARRAY['phase in','roll out']::text[]), 'phase in', '"Phase in" means to introduce something gradually and in stages rather than all at once.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'phrasal_verbs', 'The new CEO''s ambitious reforms _____ significant changes to the company''s culture within two years.', to_jsonb(ARRAY['brought about','led to']::text[]), 'brought about', '"Bring about" means to cause something to happen; the past tense "brought about" fits the completed two-year timeframe.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'phrasal_verbs', 'Despite months of negotiation, the merger _____ at the last minute when the board rejected the terms.', to_jsonb(ARRAY['fell through','collapsed']::text[]), 'fell through', '"Fall through" means a plan or agreement fails to happen after it seemed likely to succeed; "fell through" matches the last-minute collapse.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'phrasal_verbs', 'Before the client presentation in Madrid, she spent the weekend trying to _____ her rusty Spanish.', to_jsonb(ARRAY['brush up on']::text[]), 'brush up on', '"Brush up on" means to review and improve a skill or knowledge that has grown weak through lack of practice.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'phrasal_verbs', 'After the audit revealed the error, the accountant finally _____ the mistake in front of the board.', to_jsonb(ARRAY['owned up to','admitted to','confessed to']::text[]), 'owned up to', '"Own up to" means to admit responsibility for a mistake or wrongdoing; "owned up to" fits the completed admission.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'formal_register', 'In a polite formal request, it is correct to write: ''Could you _____ send me the report?'' instead of just ''Send me the report.''', to_jsonb(ARRAY['please']::text[]), 'please', 'Adding ''please'' turns a bare command into a polite formal request; omitting it sounds abrupt in professional communication.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'formal_register', 'In a formal email, it is more polite to write: ''_____ you for your assistance,'' instead of ''Thanks for your help.''', to_jsonb(ARRAY['Thank']::text[]), 'Thank', '''Thank you'' is the full formal expression of gratitude, while ''Thanks'' is the shortened, casual version used with people you know well.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'formal_register', 'In a formal email to someone you have never met, it is correct to start with ''_____ Mr Dubois,'' rather than ''Hi Mr Dubois,''.', to_jsonb(ARRAY['Dear']::text[]), 'Dear', '''Dear'' is the standard formal email opener with a surname and title; ''Hi'' is used only in informal messages to people you know.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'formal_register', 'At the end of a formal email, it is standard to write ''Best _____,'' instead of just ''Bye!''', to_jsonb(ARRAY['regards','wishes']::text[]), 'regards', '''Best regards'' is a standard formal email sign-off; ''Bye'' is too casual for professional correspondence.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'formal_register', 'In a formal report, it is more appropriate to write: ''We _____ your feedback by Friday,'' instead of ''We need your feedback by Friday.''', to_jsonb(ARRAY['require','request']::text[]), 'require', '''Require'' is the formal equivalent of ''need,'' commonly used in professional reports and business writing.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'formal_register', 'In a formal email, it is more appropriate to write: ''I have not yet _____ your invoice,'' instead of ''I haven''t got your invoice.''', to_jsonb(ARRAY['received']::text[]), 'received', '''Received'' is the formal counterpart of ''got,'' which is too conversational for professional correspondence.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'formal_register', 'In a formal report, it is more appropriate to write: ''The results were positive; _____, several issues remain unresolved,'' instead of using ''but'' to start a new sentence.', to_jsonb(ARRAY['however','nevertheless']::text[]), 'however', '''However'' is the formal connector used to introduce contrast in professional writing, replacing the more conversational ''but.'''),
  ('grammar_vocab', 'B2', 'gap_fill', 'formal_register', 'In a formal business email, it is more professional to write: ''_____, the shipment will be delayed by two days,'' instead of ''Sadly, the shipment will be delayed by two days.''', to_jsonb(ARRAY['Unfortunately','Regrettably']::text[]), 'Unfortunately', '''Unfortunately'' is the formal hedge for delivering bad news professionally; ''Sadly'' sounds overly personal and informal in business writing.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'formal_register', 'In a formal email requesting a document, it is standard to write: ''I _____ if you could send me the signed contract by Monday,'' rather than bluntly asking ''Can you send it?''', to_jsonb(ARRAY['would be grateful']::text[]), 'would be grateful', '''I would be grateful if...'' is a fixed polite formula for making formal requests in business correspondence.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'formal_register', 'In a formal email with a document attached, it is standard to write ''_____ the signed contract for your records,'' instead of ''Here''s the contract.''', to_jsonb(ARRAY['Please find attached','Attached is']::text[]), 'Please find attached', '''Please find attached'' is the fixed formal phrase used to refer to email attachments in business correspondence.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'formal_register', 'In a formal letter, it is standard to write: ''We _____ that your application has not been successful,'' rather than ''Sorry, you didn''t get the job.''', to_jsonb(ARRAY['regret to inform you','are sorry to inform you']::text[]), 'regret to inform you', '''We regret to inform you'' is the sophisticated formal phrase for delivering unwelcome news diplomatically in official correspondence.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'formal_register', 'In a formal email requesting urgent action, it is standard to write: ''We would appreciate a response _____,'' instead of ''as soon as possible.''', to_jsonb(ARRAY['at your earliest convenience']::text[]), 'at your earliest convenience', '''At your earliest convenience'' is the polished formal equivalent of ''as soon as possible,'' typical of sophisticated business correspondence.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'collocations', 'We are pleased to _____ business with your company.', to_jsonb(ARRAY['do']::text[]), 'do', '"Do business (with someone)" is the fixed collocation; you don''t say "make business" or "have business" with this meaning.'),
  ('grammar_vocab', 'A1', 'gap_fill', 'collocations', 'I''d like to _____ a bank account, please.', to_jsonb(ARRAY['open']::text[]), 'open', '"Open an account" is the standard fixed collocation used when starting a new bank account.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'collocations', 'During the training session, please _____ notes so you don''t forget anything.', to_jsonb(ARRAY['take','make']::text[]), 'take', '"Take notes" is the fixed collocation for writing down information while listening.'),
  ('grammar_vocab', 'A2', 'gap_fill', 'collocations', 'You need to _____ an effort to arrive on time every day.', to_jsonb(ARRAY['make']::text[]), 'make', '"Make an effort" is the fixed collocation; "do an effort" is incorrect and "put effort" requires "in".'),
  ('grammar_vocab', 'B1', 'gap_fill', 'collocations', 'After weeks of negotiation, both parties finally agreed to _____ the contract.', to_jsonb(ARRAY['sign','finalize']::text[]), 'sign', '"Sign a contract" is the fixed collocation for formally agreeing to its terms, distinct from drafting or reviewing it.'),
  ('grammar_vocab', 'B1', 'gap_fill', 'collocations', 'All new employees are required to _____ an induction meeting during their first week.', to_jsonb(ARRAY['attend']::text[]), 'attend', '"Attend a meeting" is the standard fixed collocation in formal workplace policy language.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'collocations', 'The deadline for all vendors to _____ their proposals is next Friday at 5 p.m.', to_jsonb(ARRAY['submit','hand in']::text[]), 'submit', '"Submit a proposal" is the fixed business collocation, especially in the context of a formal deadline.'),
  ('grammar_vocab', 'B2', 'gap_fill', 'collocations', 'Due to the supplier''s delay, the manager agreed to _____ the deadline by two days.', to_jsonb(ARRAY['extend','push back']::text[]), 'extend', '"Extend a deadline" is the fixed collocation meaning to push it back by a specific amount of time.'),
  ('grammar_vocab', 'C1', 'gap_fill', 'collocations', 'Poor communication between departments can _____ rise to unnecessary conflict.', to_jsonb(ARRAY['give']::text[]), 'give', '"Give rise to" is a fixed formal collocation meaning to cause something; no other verb fits naturally before "rise to".'),
  ('grammar_vocab', 'C1', 'gap_fill', 'collocations', 'Effective communication can _____ a pivotal role in resolving workplace conflicts.', to_jsonb(ARRAY['play','have']::text[]), 'play', '"Play a pivotal role" is the standard fixed collocation used in formal writing to describe something''s importance.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'collocations', 'The court''s ruling could _____ a precedent for future similar cases.', to_jsonb(ARRAY['set','establish']::text[]), 'set', '"Set a precedent" is the fixed idiomatic collocation for establishing an example that will guide future decisions.'),
  ('grammar_vocab', 'C2', 'gap_fill', 'collocations', 'The junior associate was accused of trying to _____ favor with senior partners by working late every night.', to_jsonb(ARRAY['curry','gain']::text[]), 'curry', '"Curry favor (with someone)" is a fixed idiom meaning to seek approval through flattery; no other verb substitutes for "curry" here.');
